public List<String> collectActiveUsers(List<User> users, Instant cutoff) {
    List<String> activeUsers = new ArrayList<>();

    for (User user : users) {
        if (!user.isOnline() || !user.lastSeenAt().isAfter(cutoff)) {
            continue;
        }

        activeUsers.add(user.name());
    }

    return activeUsers;
}

public Map<String, List<String>> groupPostsByTag(List<Post> posts) {
    Map<String, List<String>> grouped = new HashMap<>();

    for (Post post : posts) {
        for (String tag : post.tags()) {
            grouped.computeIfAbsent(tag, key -> new ArrayList<>()).add(post.slug());
        }
    }

    return grouped;
}

public String buildSummary(Project project) {
    if (project.name().isBlank()) {
        throw new IllegalArgumentException("missing project name");
    }

    String summary = (project.name() + ":" + project.branch()).toLowerCase();
    return summary.replace(" ", "-");
}

public List<ScoreEntry> topScores(List<ScoreEntry> entries) {
    return entries.stream()
        .filter(entry -> entry.score() > 0)
        .sorted(Comparator.comparingInt(ScoreEntry::score).reversed())
        .limit(5)
        .toList();
}

public int clampScore(int score, int minimum, int maximum) {
    if (score < minimum) {
        return minimum;
    }

    if (score > maximum) {
        return maximum;
    }

    return score;
}

public ScoreEntry pickBest(List<ScoreEntry> entries) {
    if (entries.isEmpty()) {
        return null;
    }

    entries.sort(Comparator.comparingInt(ScoreEntry::score).reversed());
    return entries.getFirst();
}

public RouteLanguage getRouteLanguage(Map<String, String> search) {
    String language = search.getOrDefault("language", "javascript");

    return switch (language) {
        case "java" -> RouteLanguage.JAVA;
        case "python" -> RouteLanguage.PYTHON;
        default -> RouteLanguage.JAVASCRIPT;
    };
}

public List<String> normalizeValues(List<String> values) {
    return values.stream()
        .filter(Objects::nonNull)
        .map(String::trim)
        .filter(value -> !value.isEmpty())
        .toList();
}

public Optional<String> primaryEmail(User user) {
    return user.contactMethods().stream()
        .filter(method -> method.kind() == ContactKind.EMAIL)
        .filter(ContactMethod::isVerified)
        .map(ContactMethod::value)
        .findFirst();
}

public String readFirstLine(Path path) throws IOException {
    try (BufferedReader reader = Files.newBufferedReader(path)) {
        String line = reader.readLine();

        if (line == null) {
            throw new IOException("empty file");
        }

        return line.strip();
    }
}
